CREATE TYPE "AiModelStatus" AS ENUM('ACTIVE','INACTIVE');
CREATE TABLE ai_model_versions(id uuid PRIMARY KEY,"modelKey" uuid NOT NULL,version integer NOT NULL CHECK(version>0),"previousVersionId" uuid REFERENCES ai_model_versions(id),provider varchar(160) NOT NULL,"modelName" varchar(200) NOT NULL,"providerModelVersion" varchar(160) NOT NULL,"serviceType" varchar(160) NOT NULL,"deploymentReference" varchar(500),"dataProcessingRegion" varchar(160) NOT NULL,"retentionRule" varchar(500) NOT NULL,status "AiModelStatus" NOT NULL,"changeReason" varchar(1000) NOT NULL,"sourceReference" varchar(500) NOT NULL,"sourceDate" date NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"createdBy" uuid NOT NULL REFERENCES users(id),"correlationId" uuid NOT NULL,UNIQUE("modelKey",version));
CREATE INDEX ai_model_versions_provider_name_status_idx ON ai_model_versions(provider,"modelName",status);CREATE INDEX ai_model_versions_previous_idx ON ai_model_versions("previousVersionId");
CREATE TABLE ai_use_case_definitions(id uuid PRIMARY KEY,"useCaseKey" uuid NOT NULL,version integer NOT NULL CHECK(version>0),"previousVersionId" uuid REFERENCES ai_use_case_definitions(id),code varchar(80) NOT NULL,name varchar(200) NOT NULL,purpose varchar(1000) NOT NULL,"ownerId" uuid NOT NULL REFERENCES users(id),inputs jsonb NOT NULL,outputs jsonb NOT NULL,audience jsonb NOT NULL,"riskAssessment" text NOT NULL,limitations jsonb NOT NULL,"authorizedSources" jsonb NOT NULL,"evaluationCriteria" jsonb NOT NULL,"modelVersionId" uuid NOT NULL REFERENCES ai_model_versions(id),"promptTemplate" text NOT NULL,"promptHash" char(64) NOT NULL CHECK("promptHash"~'^[a-f0-9]{64}$'),"effectiveFrom" date NOT NULL,"changeReason" varchar(1000) NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"createdBy" uuid NOT NULL REFERENCES users(id),"correlationId" uuid NOT NULL,UNIQUE("useCaseKey",version));
CREATE INDEX ai_use_case_definitions_code_effective_idx ON ai_use_case_definitions(code,"effectiveFrom");CREATE INDEX ai_use_case_definitions_model_idx ON ai_use_case_definitions("modelVersionId");CREATE INDEX ai_use_case_definitions_owner_idx ON ai_use_case_definitions("ownerId");
CREATE TABLE ai_use_case_approvals(id uuid PRIMARY KEY,"definitionId" uuid NOT NULL UNIQUE REFERENCES ai_use_case_definitions(id),note varchar(1000) NOT NULL,"approvedAt" timestamptz NOT NULL,"approvedBy" uuid NOT NULL REFERENCES users(id),"correlationId" uuid NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now());CREATE INDEX ai_use_case_approvals_approved_idx ON ai_use_case_approvals("approvedAt");
CREATE FUNCTION gsipro_validate_ai_model_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."previousVersionId" IS NULL AND NEW.version<>1 THEN RAISE EXCEPTION 'Primeira versão do modelo deve ser 1.' USING ERRCODE='check_violation';END IF;IF NEW."previousVersionId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ai_model_versions p WHERE p.id=NEW."previousVersionId" AND p."modelKey"=NEW."modelKey" AND NEW.version=p.version+1 AND NOT EXISTS(SELECT 1 FROM ai_model_versions n WHERE n."modelKey"=p."modelKey" AND n.version>p.version)) THEN RAISE EXCEPTION 'Revisão do modelo deve partir da versão mais recente.' USING ERRCODE='check_violation';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_validate_ai_model_version BEFORE INSERT ON ai_model_versions FOR EACH ROW EXECUTE FUNCTION gsipro_validate_ai_model_version();CREATE TRIGGER trg_ai_model_versions_append_only BEFORE UPDATE OR DELETE ON ai_model_versions FOR EACH ROW EXECUTE FUNCTION gsipro_competition_append_only();
CREATE FUNCTION gsipro_validate_ai_use_case() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."previousVersionId" IS NULL AND NEW.version<>1 THEN RAISE EXCEPTION 'Primeira versão do caso de uso deve ser 1.' USING ERRCODE='check_violation';END IF;IF NEW."previousVersionId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ai_use_case_definitions p WHERE p.id=NEW."previousVersionId" AND p."useCaseKey"=NEW."useCaseKey" AND p.code=NEW.code AND NEW.version=p.version+1 AND NOT EXISTS(SELECT 1 FROM ai_use_case_definitions n WHERE n."useCaseKey"=p."useCaseKey" AND n.version>p.version)) THEN RAISE EXCEPTION 'Revisão do caso de uso deve partir da versão mais recente e preservar o código.' USING ERRCODE='check_violation';END IF;IF NOT EXISTS(SELECT 1 FROM ai_model_versions m WHERE m.id=NEW."modelVersionId" AND m.status='ACTIVE') THEN RAISE EXCEPTION 'Caso de uso exige versão ativa do modelo.' USING ERRCODE='check_violation';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_validate_ai_use_case BEFORE INSERT ON ai_use_case_definitions FOR EACH ROW EXECUTE FUNCTION gsipro_validate_ai_use_case();CREATE TRIGGER trg_ai_use_cases_append_only BEFORE UPDATE OR DELETE ON ai_use_case_definitions FOR EACH ROW EXECUTE FUNCTION gsipro_competition_append_only();
CREATE FUNCTION gsipro_validate_ai_use_case_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE d ai_use_case_definitions;BEGIN SELECT * INTO d FROM ai_use_case_definitions WHERE id=NEW."definitionId";IF d.id IS NULL OR d."createdBy"=NEW."approvedBy" OR EXISTS(SELECT 1 FROM ai_use_case_definitions n WHERE n."useCaseKey"=d."useCaseKey" AND n.version>d.version) THEN RAISE EXCEPTION 'Aprovação exige versão mais recente e aprovador distinto.' USING ERRCODE='check_violation';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_validate_ai_use_case_approval BEFORE INSERT ON ai_use_case_approvals FOR EACH ROW EXECUTE FUNCTION gsipro_validate_ai_use_case_approval();CREATE TRIGGER trg_ai_use_case_approvals_append_only BEFORE UPDATE OR DELETE ON ai_use_case_approvals FOR EACH ROW EXECUTE FUNCTION gsipro_competition_append_only();
