INSERT INTO profile_permissions("profileId","permissionId","grantedAt","grantedBy") SELECT 'a2100000-0000-4000-8000-000000000001',id,now(),'00000000-0000-0000-0000-000000000000' FROM permissions WHERE code IN('ai.read','ai.manage','ai.approve');
